// Phil Won't Stop Using Your Bathroom: 16-shot cut fitted to the locked narrator take (voice B).
// Cut points come from src/timing.json, generated by `node scripts/fit-timing.mjs` from ../narration/words.json:
// each cut lands 3 frames before its line's first word. S16 opens on a close-up 12 frames before the narrator's sigh,
// holds the supplied clips at frame 0 for S16_PRE frames, then plays its supplied 151 frames untouched, so the
// REVEAL_CUES keep their local spacing. Other shots are authored on the SHOTLIST.md "design" frame ranges and
// remapped proportionally into the fitted range.
import timing from "./timing.json";

export const FPS = timing.fps;
/** S16 opens with this many frames of close-up (sigh + "Time to relax") before the supplied clips start */
export const S16_PRE = timing.s16Pre;
export const TOTAL = timing.total;

export type SetId = "bathroom" | "exterior" | "reveal";

export type Shot = {
  id: string;
  /** fitted episode range (end-exclusive) */
  from: number;
  to: number;
  /** SHOTLIST.md design range the shot code is authored against */
  designFrom: number;
  designTo: number;
  set: SetId;
  line: string; // narrator anchor
  keyStill?: number; // design-local frame of the Gate 1 key still
  keyLabel?: string;
  keyFrame?: number; // fitted absolute frame of that still
};

const SETS: Record<string, { set: SetId; line: string }> = {
  S01: { set: "bathroom", line: "Your neighbor Phil keeps breaking into your house to use your bathroom." },
  S02: { set: "bathroom", line: "And worst of all, he never flushes." },
  S03: { set: "exterior", line: "So you install a deadbolt." },
  S04: { set: "exterior", line: "But Phil just climbs through the window." },
  S05: { set: "exterior", line: "You install metal bars. Phil files through them." },
  S06: { set: "exterior", line: "So you board up every window. But now your house looks like it's from Detroit." },
  S07: { set: "exterior", line: "And Phil drives straight through your garage. This madness needs to stop!" },
  S08: { set: "exterior", line: "So you buy a highly trained guard dog." },
  S09: { set: "exterior", line: "But Phil brings him a rotisserie chicken." },
  S10: { set: "exterior", line: "The dog's name is now Gregory." },
  S11: { set: "exterior", line: "You build a twelve-foot concrete wall." },
  S12: { set: "exterior", line: "But Phil did pole vault in high school." },
  S13: { set: "exterior", line: "So you spend your entire life savings turning your house into a maximum-security fortress." },
  S14: { set: "exterior", line: "Steel doors. Laser sensors. Armed guards." },
  S15: { set: "bathroom", line: "There's absolutely no way Phil's getting in now." },
  S16: { set: "reveal", line: "Time to relax." },
};

export const SHOTS: Shot[] = timing.shots.map((s) => ({ ...s, ...SETS[s.id] }));

/** S16 local cue frames (zero-based, relative to S16 start). Never retime these independently. */
export const REVEAL_CUES = {
  bathOnlyEnd: 37,
  panStart: 38,
  panEnd: 107,
  sideEye: [107, 119] as const,
  blink: [126, 131] as const,
  fart: 138,
  blackFrom: 146, // last five frames (146-150) are a black edit
};

/** `local` is in DESIGN frames (what the set code is authored against); for S16 it is the SUPPLIED clip frame
 *  (negative during the close-up pre-roll). `fitted` is the real offset into the shot. */
export const shotAt = (frame: number): { shot: Shot; local: number; fitted: number } => {
  const shot = SHOTS.find((s) => frame >= s.from && frame < s.to) ?? SHOTS[SHOTS.length - 1];
  const fitted = frame - shot.from;
  const dDur = shot.designTo - shot.designFrom, fDur = shot.to - shot.from;
  const local = shot.id === "S16" ? fitted - S16_PRE : Math.min(dDur - 1, Math.floor((fitted * dDur) / fDur));
  return { shot, local, fitted };
};

/** Absolute (fitted) frames of the Gate 1 key stills. */
export const KEY_STILLS = SHOTS.filter((s) => s.keyFrame !== undefined).map((s) => ({ id: s.id, label: s.keyLabel!, frame: s.keyFrame! }));

// sanity: contiguous cover of 0..TOTAL, S16 untouched
SHOTS.forEach((s, i) => {
  if (i > 0 && SHOTS[i - 1].to !== s.from) throw new Error(`gap before ${s.id}`);
});
if (SHOTS[SHOTS.length - 1].to !== TOTAL) throw new Error("timeline does not end at TOTAL");
const s16 = SHOTS[SHOTS.length - 1];
if (s16.to - s16.from !== S16_PRE + 151) throw new Error("S16 must be the close-up pre-roll + its 151 supplied frames");
